package com.gientech.ragauthservice.domain.service.impl;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.gientech.ragauthservice.domain.entity.InterfaceInfo;import com.gientech.ragauthservice.domain.repository.InterfaceInfoRepository;import com.gientech.ragauthservice.domain.service.InterfaceInfoDomainService;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import java.util.List;@Servicepublic class InterfaceInfoDomainServiceImpl implements InterfaceInfoDomainService {    @Autowired    private InterfaceInfoRepository interfaceInfoRepository;    @Override    public InterfaceInfo findById(Long id) {        return interfaceInfoRepository.findById(id);    }    @Override    public Boolean save(InterfaceInfo interfaceInfo) {        return interfaceInfoRepository.save(interfaceInfo);    }    @Override    public Boolean updateById(InterfaceInfo interfaceInfo) {        return interfaceInfoRepository.updateById(interfaceInfo);    }    @Override    public Page<InterfaceInfo> list(Long pageNo, Long pageSize) {        return interfaceInfoRepository.list(pageNo, pageSize);    }    @Override    public Page<InterfaceInfo> listExtInterfaces(Long pageNo, Long pageSize, String fuzzy) {        return interfaceInfoRepository.listExtInterfaces(pageNo, pageSize, fuzzy);    }    @Override    public Boolean deleteById(Long id) {        return interfaceInfoRepository.deleteById(id);    }    @Override    public List<InterfaceInfo> findByAppName(String appName) {        return interfaceInfoRepository.findByAppName(appName);    }    @Override    public int saveBatch(List<InterfaceInfo> needToInserts) {        return interfaceInfoRepository.saveBatch(needToInserts);    }    @Override    public boolean deleteByAppName(String appName) {        interfaceInfoRepository.deleteByAppName(appName);        return true;    }    @Override    public List<InterfaceInfo> findByIds(List<Long> resourceIds) {        return interfaceInfoRepository.findByIds(resourceIds);    }}